    // Comprobaciones estructurales (admitiendo claves JSON con comillas o identificadores TS)
    const hasKey = (key: string) => content.includes(`"${key}":`) || content.includes(`${key}:`);
    const hasMetadata = hasKey('metadata');
    const hasPrep = hasKey('prep');
    const hasRoute = hasKey('route');
    const hasFormalization = hasKey('formalization');
    const hasPractice = hasKey('practice');
    const hasMini = hasKey('mini');
    const hasRecovery = hasKey('recovery');
    const hasSummary = hasKey('summaryIdeas') || hasKey('summary');
    const hasClosure = hasKey('closure') || hasKey('paso8_cierre');

    // Comprobación anti-placeholders
    const hasDummyAndamiaje = content.includes('Opción con andamiaje A');

    // Comprobación reactivos psicométricos (opciones A-D)
    const hasOptions = content.includes('options:');

    const issues: string[] = [];
    if (!hasMetadata) issues.push('Falta metadata');
    if (!hasPrep) issues.push('Falta prep');
    if (!hasRoute) issues.push('Falta route');
    if (!hasFormalization) issues.push('Falta formalization');
    if (!hasPractice) issues.push('Falta practice');
    if (!hasMini) issues.push('Falta mini');
    if (!hasRecovery) issues.push('Falta recovery');
    if (!hasSummary) issues.push('Falta summaryIdeas');
    if (!hasClosure) issues.push('Falta closure/paso8_cierre');
    if (hasDummyAndamiaje) issues.push('Detectado placeholder "Opción con andamiaje A"');

    const status = issues.length === 0 ? 'OK' : `FALLO (${issues.join(', ')})`;
    if (issues.length > 0) allPassed = false;

    console.log(`  - ${f}: ${status}`);
    summaryResults.push({ file: f, label: oa.label, status, issues });
