                className="bg-white hover:bg-[#12a1a4] text-[#1c3257] hover:text-white font-bold p-3.5 rounded-xl border border-[#bac5d0] hover:border-[#12a1a4] text-sm transition-all shadow-sm cursor-pointer"
              >
                {opt}
              </button>
            ))}
          </div>
