      </div>

      {/* Modal / Drawer para consultar lectura sin perder la pregunta ni reiniciar respuesta */}
      {showReadingConsult && (
        <div className="fixed inset-0 z-50 bg-slate-950/60 backdrop-blur-xs flex items-center justify-center p-4 animate-fadeIn">
